-- ==============================================================
-- SCRIPT DE MIGRACIÓN COMPLETO DE BASE DE DATOS SUPABASE
-- PORTAL DE EVALUACIÓN DE PROYECTOS ESTRATÉGICOS (DMQ)
-- ==============================================================
-- Instrucciones:
-- 1. Crear un nuevo proyecto en https://supabase.com
-- 2. Ir a SQL Editor en el menú lateral izquierdo
-- 3. Pegar todo este script y hacer clic en RUN.
-- ==============================================================

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. TABLA DE PROYECTOS
CREATE TABLE IF NOT EXISTS proyectos (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    nombre TEXT UNIQUE NOT NULL,
    categoria TEXT,
    ubicacion TEXT,
    extension TEXT,
    fecha_inauguracion TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 2. TABLA DE ESTADÍSTICAS DE SEGURIDAD
CREATE TABLE IF NOT EXISTS seguridad_estadisticas (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    proyecto_id UUID REFERENCES proyectos(id) ON DELETE CASCADE,
    anio TEXT NOT NULL,
    variable TEXT NOT NULL,
    valor NUMERIC,
    tipo TEXT DEFAULT 'observado',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 3. TABLA DE REGISTROS DE ECONOMÍA (LUAEs)
CREATE TABLE IF NOT EXISTS economia_registros (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sector_raw TEXT,
    movimiento_raw TEXT,
    fecha_impresion DATE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_economia_registros_sector ON economia_registros(sector_raw);
CREATE INDEX IF NOT EXISTS idx_economia_registros_fecha ON economia_registros(fecha_impresion);

-- 4. TABLA DE VALOR DE SUELO
CREATE TABLE IF NOT EXISTS valor_suelo (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    proyecto TEXT NOT NULL,
    descripcion TEXT,
    valor_2022_2023 NUMERIC,
    valor_2024 NUMERIC,
    valor_2026 NUMERIC,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_valor_suelo_proyecto ON valor_suelo(proyecto);

-- 5. TABLA DE FICHAS DE SENDEROS (Metadatos institucionales)
CREATE TABLE IF NOT EXISTS senderos_fichas (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    proyecto_id UUID REFERENCES proyectos(id) ON DELETE CASCADE,
    anio INT,
    ejecutor TEXT,
    presupuesto TEXT,
    extension TEXT,
    beneficiarios TEXT,
    fecha TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- ==============================================================
-- HABILITAR POLÍTICAS DE LECTURA PÚBLICA (RLS PARA FRONTEND)
-- ==============================================================
ALTER TABLE proyectos ENABLE ROW LEVEL SECURITY;
ALTER TABLE seguridad_estadisticas ENABLE ROW LEVEL SECURITY;
ALTER TABLE economia_registros ENABLE ROW LEVEL SECURITY;
ALTER TABLE valor_suelo ENABLE ROW LEVEL SECURITY;
ALTER TABLE senderos_fichas ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Lectura pública de proyectos" ON proyectos FOR SELECT USING (true);
CREATE POLICY "Lectura pública de seguridad" ON seguridad_estadisticas FOR SELECT USING (true);
CREATE POLICY "Lectura pública de economía" ON economia_registros FOR SELECT USING (true);
CREATE POLICY "Lectura pública de valor suelo" ON valor_suelo FOR SELECT USING (true);
CREATE POLICY "Lectura pública de senderos" ON senderos_fichas FOR SELECT USING (true);

